customCSS:
/* ── TableTopia — Fine Dining Theme (matched to capstone deck design) ──── */
/* Palette: near-black #0D0B07 · parchment #F0EBE0 · burgundy #7B1D30 · gold #C9973E */

/* ── Navigation bar (very dark near-black, gold accent) ─────────────────── */
.siteforceNavigationMenuHorizontal,
.communitiesHeader,
.navbarContainer,
.forceComNavBar,
.napili-header,
.comm-header,
.forceCommunityNavigation,
.napiliHeader {
  background-color: #0D0B07 !important;
  border-bottom: 3px solid #C9973E !important;
  box-shadow: 0 2px 12px rgba(0,0,0,.4) !important;
}

/* Nav links — white on dark */
.siteforceNavigationMenuHorizontal a,
.siteforceNavigationMenuHorizontal span,
.communitiesHeader a,
.forceComNavBar a,
.napili-header a,
.forceCommunityNavigation a,
.napiliHeader a,
[class*='navItem'] a,
[class*='navBar'] a {
  color: #FFFFFF !important;
  font-weight: 500 !important;
}
.siteforceNavigationMenuHorizontal a:hover,
.forceComNavBar a:hover,
.napili-header a:hover {
  color: #C9973E !important;
  text-decoration: none !important;
}

/* Site name / logo text */
.siteTitle,
.siteTitleLabel,
.napili-header .comm-logo,
.logoImage {
  color: #FFFFFF !important;
  font-weight: 800 !important;
}

/* ── Page & content background (warm parchment) ─────────────────────────── */
body,
.siteforceContentArea,
.forceCommunityContent {
  background-color: #F0EBE0 !important;
  color: #1A1208 !important;
}

.siteforceContentArea p,
.siteforceContentArea span,
.siteforceContentArea li,
.siteforceContentArea label,
.siteforceContentArea td,
.siteforceContentArea th,
.comm-layout-column p,
.comm-layout-column span:not([class*='nav']):not([class*='button']) {
  color: #1A1208 !important;
}

/* ── Headings — serif, burgundy ─────────────────────────────────────────── */
h1, h2, h3, h4, h5, h6,
.slds-text-heading_large,
.slds-text-heading_medium,
.slds-text-heading_small,
.slds-text-title,
.napili-section-heading,
[class*='sectionTitle'] {
  color: #7B1D30 !important;
  font-weight: 700 !important;
  font-family: Georgia, 'Playfair Display', 'Times New Roman', serif !important;
}

/* ── Primary action buttons → burgundy ─────────────────────────────────── */
.slds-button_brand,
.slds-button--brand,
.forceActionButton .slds-button_brand,
.cCommunityButton.slds-button_brand,
button.slds-button_brand {
  background-color: #7B1D30 !important;
  border-color: #7B1D30 !important;
  color: #FFFFFF !important;
  border-radius: 8px !important;
  font-weight: 600 !important;
  text-shadow: none !important;
}
.slds-button_brand:hover,
.slds-button--brand:hover {
  background-color: #5E1623 !important;
  border-color: #5E1623 !important;
  color: #FFFFFF !important;
  transform: translateY(-1px) !important;
}

/* Neutral / outline buttons */
.slds-button_neutral, .slds-button--neutral {
  color: #7B1D30 !important;
  border-color: #C9973E !important;
  background-color: transparent !important;
  border-radius: 8px !important;
  font-weight: 500 !important;
}
.slds-button_neutral:hover {
  background-color: #F5EDD8 !important;
  color: #7B1D30 !important;
}

/* ── Links — burgundy ───────────────────────────────────────────────────── */
a:not([class*='nav']):not([class*='header__']) {
  color: #7B1D30 !important;
}
a:not([class*='nav']):not([class*='header__']):hover {
  color: #5E1623 !important;
  text-decoration: underline !important;
}

/* ── Cards & result tiles (cream bg, gold border) ──────────────────────── */
.slds-card,
.communitiesCard,
.forceCommunitySearchResult,
.selfServiceTopic,
.napili-article-card,
.napili-tile,
.selfServiceTile {
  border-radius: 10px !important;
  box-shadow: 0 1px 4px rgba(0,0,0,.08) !important;
  border: 1px solid #C9973E !important;
  background: #FAF7F2 !important;
  color: #1A1208 !important;
}
.slds-card:hover,
.forceCommunitySearchResult:hover,
.napili-article-card:hover,
.napili-tile:hover {
  box-shadow: 0 8px 18px rgba(123,29,48,.12) !important;
  transform: translateY(-2px) !important;
}

.slds-card__header-title,
.slds-card__header-title a,
.napili-article-card .article-title,
.forceCommunitySearchResult .result-title {
  color: #7B1D30 !important;
  font-weight: 700 !important;
  font-family: Georgia, 'Playfair Display', serif !important;
}
.slds-card__header {
  background: #F5EDD8 !important;
  border-bottom: 1px solid #C9973E !important;
}
.slds-card__body,
.napili-article-card p,
.forceCommunitySearchResult p {
  color: #3D2B1A !important;
}

/* ── Form inputs ────────────────────────────────────────────────────────── */
.slds-input,
.slds-select,
.slds-textarea,
.forceCommunitySearchBox input,
input[type='text'],
input[type='email'],
input[type='search'],
select {
  background-color: #FAF7F2 !important;
  color: #1A1208 !important;
  border: 1.5px solid #94A3B8 !important;
  border-radius: 8px !important;
}
.slds-input:focus,
.forceCommunitySearchBox input:focus {
  border-color: #C9973E !important;
  box-shadow: 0 0 0 3px rgba(201,151,62,.2) !important;
  color: #1A1208 !important;
}
.slds-form-element__label, label {
  color: #3D2B1A !important;
  font-weight: 500 !important;
}
.slds-input::placeholder { color: #94A3B8 !important; }

/* ── Headline banner ─────────────────────────────────────────────────────── */
.forceCommunityHeadline.homePageHeadline,
.napili-headline {
  padding-bottom: 1rem !important;
}
.forceCommunityHeadline .headline-title,
.comm-headline-title {
  color: #7B1D30 !important;
  font-weight: 800 !important;
  font-family: Georgia, 'Playfair Display', serif !important;
}
.forceCommunityHeadline .headline-text,
.comm-headline-text {
  color: #3D2B1A !important;
}

/* ── Ask Community / publisher box ──────────────────────────────────────── */
.forcePublisher,
.napili-publisher,
.comm-publisher {
  background: #FAF7F2 !important;
  border: 1px solid #C9973E !important;
  border-radius: 10px !important;
  color: #1A1208 !important;
}
.forcePublisher .slds-input,
.napili-publisher textarea { color: #1A1208 !important; }

/* ── Home Tabs ──────────────────────────────────────────────────────────── */
.napili-tab,
.comm-tab {
  color: #3D2B1A !important;
  font-weight: 500 !important;
  border-bottom: 2px solid transparent !important;
}
.napili-tab.active,
.napili-tab:hover,
.comm-tab.active {
  color: #7B1D30 !important;
  border-bottom-color: #C9973E !important;
}

/* ── Sidebar widgets ─────────────────────────────────────────────────────── */
.selfService-leaderboard,
.forceCommunityReputationLeaderboard,
.napili-sidebar-widget,
.selfServiceTopicTrendingArticles,
.forceCommunityTrendingTopics {
  border-radius: 10px !important;
  border: 1px solid #C9973E !important;
  background: #FAF7F2 !important;
  color: #1A1208 !important;
  box-shadow: 0 1px 3px rgba(0,0,0,.07) !important;
}
.napili-sidebar-widget h2,
.napili-sidebar-widget h3,
[class*='widgetTitle'] {
  color: #7B1D30 !important;
  font-weight: 700 !important;
  font-family: Georgia, 'Playfair Display', serif !important;
}
.napili-sidebar-widget li,
.napili-sidebar-widget span,
.napili-sidebar-widget a { color: #3D2B1A !important; }
.napili-sidebar-widget a:hover { color: #7B1D30 !important; }

/* ── Badges & pills ─────────────────────────────────────────────────────── */
.slds-badge {
  background-color: #F5EDD8 !important;
  color: #7B1D30 !important;
  border-radius: 9999px !important;
  font-weight: 600 !important;
  border: 1px solid rgba(201,151,62,.3) !important;
}

/* ── Feed items ──────────────────────────────────────────────────────────── */
.forceCommunityFeed .message,
.napili-feed-item {
  background: #FAF7F2 !important;
  border: 1px solid #C9973E !important;
  border-radius: 8px !important;
  color: #1A1208 !important;
}
.forceCommunityFeed .author-name,
.napili-feed-item .author { color: #7B1D30 !important; font-weight: 600 !important; font-family: Georgia, serif !important; }
.forceCommunityFeed .feed-body,
.napili-feed-item .body { color: #3D2B1A !important; }

/* ── Footer ─────────────────────────────────────────────────────────────── */
.napili-footer,
.siteforceFooter,
.comm-footer,
[class*='napiliFooter'],
.siteforceBody > footer {
  background-color: #0D0B07 !important;
  color: rgba(255,255,255,.85) !important;
  border-top: 3px solid #C9973E !important;
}
.napili-footer *,
[class*='napiliFooter'] * { color: rgba(255,255,255,.8) !important; }
.napili-footer a,
[class*='napiliFooter'] a { color: rgba(255,255,255,.75) !important; }
.napili-footer a:hover { color: #C9973E !important; }

/* ── Recommendations widget ──────────────────────────────────────────────── */
.forceCommunityRecommendations {
  background: #FAF7F2 !important;
  border: 1px solid #C9973E !important;
  border-radius: 10px !important;
  color: #1A1208 !important;
}

/* ── Search results ─────────────────────────────────────────────────────── */
.napili-search-results h2 { color: #7B1D30 !important; font-family: Georgia, serif !important; }
.napili-search-results .result-excerpt { color: #3D2B1A !important; }

/* ── Login page ─────────────────────────────────────────────────────────── */
.loginContainer, .forceLoginPage {
  background: linear-gradient(140deg, #0D0B07 0%, #1A1208 100%) !important;
}
.loginBox, .forceLoginBox {
  background: #FAF7F2 !important;
  border-radius: 14px !important;
  box-shadow: 0 20px 40px rgba(0,0,0,.22) !important;
  border: 1px solid #C9973E !important;
}
.loginBox h1, .loginBox h2,
.loginBox label, .loginBox p { color: #1A1208 !important; }

/* ── Toasts / alerts ─────────────────────────────────────────────────────── */
.slds-notify_toast.slds-theme_success { background-color: #16A34A !important; color: #FFFFFF !important; }
.slds-notify_toast.slds-theme_error   { background-color: #DC2626 !important; color: #FFFFFF !important; }
.slds-notify_toast.slds-theme_info    { background-color: #7B1D30 !important; color: #FFFFFF !important; }
.slds-notify__close { color: #FFFFFF !important; }

/* ── ADA / WCAG 2.1 AA ──────────────────────────────────────────────────── */

a:focus-visible,
button:focus-visible,
[role='button']:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid #C9973E !important;
  outline-offset: 2px !important;
  box-shadow: 0 0 0 5px rgba(201,151,62,.25) !important;
}


.slds-input,
.slds-select,
.slds-textarea,
input[type='text'],
input[type='email'],
input[type='search'],
input[type='date'],
select {
  border-color: #94A3B8 !important;
}

/* ── Search bar region (the gray utility bar below header) ───────────────── */
.comm-search-bar,
.napili-search-bar,
.forceCommunitySearchBox,
.siteforceSearchBox,
.napiliSearchBar,
[class*='communitySearchBox'],
[class*='searchBarContainer'],
[class*='SearchBarContainer'],
.comm-layout-column .searchBar,
.communitiesSearchBar {
  background-color: #F0EBE0 !important;
  border-bottom: 1px solid rgba(201,151,62,.35) !important;
}

/* Search area input */
.forceCommunitySearchBox .slds-input,
.napili-search-bar input,
.siteforceSearchBox input[type='search'],
.siteforceSearchBox input[type='text'] {
  background-color: #FFFFFF !important;
  border: 1.5px solid #94A3B8 !important;
  color: #1A1208 !important;
}

/* Search button — burgundy */
.forceCommunitySearchBox button,
.forceCommunitySearchBox .slds-button,
.napili-search-bar button,
.siteforceSearchBox button,
[class*='searchButton'],
[class*='SearchButton'] {
  background-color: #7B1D30 !important;
  border-color: #7B1D30 !important;
  color: #FFFFFF !important;
  font-weight: 600 !important;
}
.forceCommunitySearchBox button:hover,
.siteforceSearchBox button:hover {
  background-color: #5E1623 !important;
  border-color: #5E1623 !important;
}

/* ── Global Navigation / HOME·TOPICS breadcrumb bar ──────────────────────── */
.forceComNavBar,
.napili-nav-bar,
.comm-nav-bar,
.napiliNavBar,
.forceCommunityGlobalNavigation,
.cCommunityGlobalNavigation,
[class*='globalNavigation'],
[class*='GlobalNavigation'],
.siteforceNavigation {
  background-color: #1A1208 !important;
  border-bottom: 1px solid rgba(201,151,62,.2) !important;
}

.forceComNavBar a,
.napili-nav-bar a,
.napiliNavBar a,
.forceCommunityGlobalNavigation a,
[class*='globalNavigation'] a,
[class*='globalNavigation'] span {
  color: rgba(255,255,255,.72) !important;
  font-weight: 500 !important;
}
.forceComNavBar a:hover,
.napili-nav-bar a:hover,
[class*='globalNavigation'] a:hover {
  color: #C9973E !important;
}

/* Active nav item in the breadcrumb bar */
.forceComNavBar .active a,
.napili-nav-bar .active,
[class*='globalNavigation'] .active {
  color: #C9973E !important;
  border-bottom: 2px solid #C9973E !important;
}

/* ── Community Headline (TABLETOPIA SUPPORT area) ────────────────────────── */
.forceCommunityHeadline,
.napili-headline,
.comm-headline {
  background: transparent !important;
}
.forceCommunityHeadline h1,
.forceCommunityHeadline h2,
.forceCommunityHeadline .slds-text-heading_large,
.napili-headline h1,
.napili-headline h2,
.comm-headline-title,
.napili-headline .headline-title {
  color: #7B1D30 !important;
  font-family: Georgia, 'Playfair Display', serif !important;
  font-weight: 800 !important;
  letter-spacing: -0.01em !important;
  text-transform: none !important;
}

/* ── Profile menu / user area ────────────────────────────────────────────── */
.selfService-userProfileMenu,
.forceCommunityUserProfileMenu,
[class*='userProfileMenu'],
[class*='profileMenu'] {
  background-color: #F0EBE0 !important;
}
.selfService-userProfileMenu a,
[class*='userProfileMenu'] a,
[class*='loginButton'] {
  color: #7B1D30 !important;
  border-color: #C9973E !important;
}
